// The conditions stay as in QuantLib, so that they can be compared with the source.
#![allow(unused_parens)]
#![allow(
    clippy::manual_range_contains,
    clippy::nonminimal_bool,
    clippy::if_same_then_else,
    clippy::needless_return
)]
#![allow(clippy::collapsible_if, clippy::collapsible_else_if)]

use super::{easter_monday, is_weekend, Day};
#[allow(unused_imports)]
use crate::time::Weekday::{Friday, Monday, Saturday, Sunday, Thursday, Tuesday, Wednesday};

pub(in crate::time::calendar) fn botswana(x: &Day) -> bool {
    let (d, m, w, dd, y) = (x.d, x.m, x.w, x.dd, x.y);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day (possibly moved to Monday or Tuesday)
            || ((d == 1 || (d == 2 && w == Monday) || (d == 3 && w == Tuesday)) 
                && m == 1)
            // Good Friday
            || (dd == em - 3)
            // Easter Monday
            || (dd == em)
            // Labour Day, May 1st (possibly moved to Monday)
            || ((d == 1 || (d == 2 && w == Monday))
                && m == 5)
            // Ascension
            || (dd == em + 38)
            // Sir Seretse Khama Day, July 1st (possibly moved to Monday)
            || ((d == 1 || (d == 2 && w == Monday))
                && m == 7)
            // Presidents' Day (third Monday of July)
            || ((d >= 15 && d <= 21) && w == Monday && m == 7)
            // Independence Day, September 30th (possibly moved to Monday)
            || ((d == 30 && m == 9) || 
                (d == 1  && w == Monday && m == 10))
            // Botswana Day, October 1st (possibly moved to Monday or Tuesday)
            || ((d == 1 || (d == 2 && w == Monday) || (d == 3 && w == Tuesday)) 
                && m == 10)
            // Christmas
            || (d == 25 && m == 12)
            // Boxing Day (possibly moved to Monday)
            || ((d == 26 || (d == 27 && w == Monday))
                && m == 12)
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn south_africa(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day (possibly moved to Monday)
            || ((d == 1 || (d == 2 && w == Monday)) && m == 1)
            // Good Friday
            || (dd == em-3)
            // Family Day
            || (dd == em)
            // Human Rights Day, March 21st (possibly moved to Monday)
            || ((d == 21 || (d == 22 && w == Monday))
                && m == 3)
            // Freedom Day, April 27th (possibly moved to Monday)
            || ((d == 27 || (d == 28 && w == Monday))
                && m == 4)
            // Election Day, April 14th 2004
            || (d == 14 && m == 4 && y == 2004)
            // Workers Day, May 1st (possibly moved to Monday)
            || ((d == 1 || (d == 2 && w == Monday))
                && m == 5)
            // Youth Day, June 16th (possibly moved to Monday)
            || ((d == 16 || (d == 17 && w == Monday))
                && m == 6)
            // National Women's Day, August 9th (possibly moved to Monday)
            || ((d == 9 || (d == 10 && w == Monday))
                && m == 8)
            // Heritage Day, September 24th (possibly moved to Monday)
            || ((d == 24 || (d == 25 && w == Monday))
                && m == 9)
            // Day of Reconciliation, December 16th
            // (possibly moved to Monday)
            || ((d == 16 || (d == 17 && w == Monday))
                && m == 12)
            // Christmas
            || (d == 25 && m == 12)
            // Day of Goodwill (possibly moved to Monday)
            || ((d == 26 || (d == 27 && w == Monday))
                && m == 12)
            // one-shot: Election day 2009
            || (d == 22 && m == 4 && y == 2009)
            // one-shot: Election day 2016
            || (d == 3 && m == 8 && y == 2016)
            // one-shot: Election day 2021
            || (d == 1 && m == 11 && y == 2021)
            // one-shot: In lieu of Christmas falling on Sunday in 2022
            || (d == 27 && m == 12 && y == 2022)
            // one-shot: Special holiday to celebrate winning of Rugby World Cup 2023
            || (d == 15 && m == 12 && y == 2023)
            // one-shot: Election day 2024
            || (d == 29 && m == 5 && y == 2024)
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn turkey(x: &Day) -> bool {
    let (d, m, y, w) = (x.d, x.m, x.y, x.w);
    if is_weekend(w)
            // New Year's Day
            || (d == 1 && m == 1)
            // 23 nisan / National Holiday
            || (d == 23 && m == 4)
            // 1 may/ National Holiday
            || (d == 1 && m == 5)
            // 19 may/ National Holiday
            || (d == 19 && m == 5)
            // 15 july / National Holiday (since 2017)
            || (d == 15 && m == 7 && y >= 2017)
            // 30 aug/ National Holiday
            || (d == 30 && m == 8)
            //29 ekim  National Holiday
            || (d == 29 && m == 10)
    {
        return false;
    }
    // Local Holidays
    if y == 2004 {
        // Kurban
        if (m == 2 && d <= 4)
            // Ramadan
                || (m == 11 && d >= 14 && d <= 16)
        {
            return false;
        }
    } else if y == 2005 {
        // Kurban
        if (m == 1 && d >= 19 && d <= 21)
            // Ramadan
                || (m == 11 && d >= 2 && d <= 5)
        {
            return false;
        }
    } else if y == 2006 {
        // Kurban
        if (m == 1 && d >= 10 && d <= 13)
            // Ramadan
                || (m == 10 && d >= 23 && d <= 25)
            // Kurban
                || (m == 12 && d == 31)
        {
            return false;
        }
    } else if y == 2007 {
        // Kurban
        if (m == 1 && d <= 3)
            // Ramadan
                || (m == 10 && d >= 12 && d <= 14)
            // Kurban
                || (m == 12 && d >= 20 && d <= 23)
        {
            return false;
        }
    } else if y == 2008 {
        // Ramadan
        if (m == 9 && d == 30)
                || (m == 10 && d <= 2)
            // Kurban
                || (m == 12 && d >= 8 && d <= 11)
        {
            return false;
        }
    } else if y == 2009 {
        // Ramadan
        if (m == 9 && d >= 20 && d <= 22)
            // Kurban
                || (m == 11 && d >= 27 && d <= 30)
        {
            return false;
        }
    } else if y == 2010 {
        // Ramadan
        if (m == 9 && d >= 9 && d <= 11)
            // Kurban
                || (m == 11 && d >= 16 && d <= 19)
        {
            return false;
        }
    } else if y == 2011 {
        // not clear from borsainstanbul.com
        if (m == 10 && d == 1) || (m == 11 && d >= 9 && d <= 13) {
            return false;
        }
    } else if y == 2012 {
        // Ramadan
        if (m == 8 && d >= 18 && d <= 21)
            // Kurban
                || (m == 10 && d >= 24 && d <= 28)
        {
            return false;
        }
    } else if y == 2013 {
        // Ramadan
        if (m == 8 && d >= 7 && d <= 10)
            // Kurban
                || (m == 10 && d >= 14 && d <= 18)
            // additional holiday for Republic Day
                || (m == 10 && d == 28)
        {
            return false;
        }
    } else if y == 2014 {
        // Ramadan
        if (m == 7 && d >= 27 && d <= 30)
            // Kurban
                || (m == 10 && d >= 4 && d <= 7)
            // additional holiday for Republic Day
                || (m == 10 && d == 29)
        {
            return false;
        }
    } else if y == 2015 {
        // Ramadan
        if (m == 7 && d >= 17 && d <= 19)
                // Kurban
                || (m == 10 && d >= 24 && d <= 27)
        {
            return false;
        }
    } else if y == 2016 {
        // Ramadan
        if (m == 7 && d >= 5 && d <= 7)
                // Kurban
                || (m == 9 && d >= 12 && d <= 15)
        {
            return false;
        }
    } else if y == 2017 {
        // Ramadan
        if (m == 6 && d >= 25 && d <= 27)
                // Kurban
                || (m == 9 && d >= 1 && d <= 4)
        {
            return false;
        }
    } else if y == 2018 {
        // Ramadan
        if (m == 6 && d >= 15 && d <= 17)
                // Kurban
                || (m == 8 && d >= 21 && d <= 24)
        {
            return false;
        }
    } else if y == 2019 {
        // Ramadan
        if (m == 6 && d >= 4 && d <= 6)
                // Kurban
                || (m == 8 && d >= 11 && d <= 14)
        {
            return false;
        }
    } else if y == 2020 {
        // Ramadan
        if (m == 5 && d >= 24 && d <= 26)
                // Kurban
                || (m == 7 && d == 31) || (m == 8 && d >= 1 && d <= 3)
        {
            return false;
        }
    } else if y == 2021 {
        // Ramadan
        if (m == 5 && d >= 13 && d <= 15)
                // Kurban
                || (m == 7 && d >= 20 && d <= 23)
        {
            return false;
        }
    } else if y == 2022 {
        // Ramadan
        if (m == 5 && d >= 2 && d <= 4)
                // Kurban
                || (m == 7 && d >= 9 && d <= 12)
        {
            return false;
        }
    } else if y == 2023 {
        // Ramadan
        if (m == 4 && d >= 21 && d <= 23)
                // Kurban
                // July 1 is also a holiday but falls on a Saturday which is already flagged
                || (m == 6 && d >= 28 && d <= 30)
        {
            return false;
        }
    } else if y == 2024 {
        // Note: Holidays >= 2024 are not yet officially anounced by borsaistanbul.com
        // and need further validation
        // Ramadan
        if (m == 4 && d >= 10 && d <= 12)
                // Kurban
                || (m == 6 && d >= 17 && d <= 19)
        {
            return false;
        }
    } else if y == 2025 {
        // Ramadan
        if (m == 3 && d == 31) || (m == 4 && d >= 1 && d <= 2)
                // Kurban
                || (m == 6 && d >= 6 && d <= 9)
        {
            return false;
        }
    } else if y == 2026 {
        // Ramadan
        if (m == 3 && d >= 20 && d <= 22)
                // Kurban
                || (m == 5 && d >= 26 && d <= 29)
        {
            return false;
        }
    } else if y == 2027 {
        // Ramadan
        if (m == 3 && d >= 10 && d <= 12)
                // Kurban
                || (m == 5 && d >= 16 && d <= 19)
        {
            return false;
        }
    } else if y == 2028 {
        // Ramadan
        if (m == 2 && d >= 27 && d <= 29)
                // Kurban
                || (m == 5 && d >= 4 && d <= 7)
        {
            return false;
        }
    } else if y == 2029 {
        // Ramadan
        if (m == 2 && d >= 15 && d <= 17)
                // Kurban
                || (m == 4 && d >= 23 && d <= 26)
        {
            return false;
        }
    } else if y == 2030 {
        // Ramadan
        if (m == 2 && d >= 5 && d <= 7)
                // Kurban
                || (m == 4 && d >= 13 && d <= 16)
        {
            return false;
        }
    } else if y == 2031 {
        // Ramadan
        if (m == 1 && d >= 25 && d <= 27)
                // Kurban
                || (m == 4 && d >= 2 && d <= 5)
        {
            return false;
        }
    } else if y == 2032 {
        // Ramadan
        if (m == 1 && d >= 14 && d <= 16)
                // Kurban
                || (m == 3 && d >= 21 && d <= 24)
        {
            return false;
        }
    } else if y == 2033 {
        // Ramadan
        if (m == 1 && d >= 3 && d <= 5) || (m == 12 && d == 23)
                // Kurban
                || (m == 3 && d >= 11 && d <= 14)
        {
            return false;
        }
    } else if y == 2034 {
        // Ramadan
        if (m == 12 && d >= 12 && d <= 14) 
                // Kurban
                || (m == 2 && d == 28) || (m == 3 && d >= 1 && d <= 3)
        {
            return false;
        }
    }
    true
}
